(()=>{let L=new URLSearchParams(location.search).get('lang')==='en'?1:0,D,P,Q;const app=document.querySelector('#app');const t=(a,b)=>L?b:a,v=x=>Array.isArray(x)?x[L]:x,m=x=>Number(x).toFixed(2),n=x=>Number(x).toLocaleString('en-AU'),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const link=page=>(page==='hub'?'index':page)+'.html?lang='+(L?'en':'zh-CN');const gameLink=b=>b.path+'?mode=solo&v=20260925-r6&lang='+(L?'en':'zh-CN');const score=b=>b.scores?b.scores.reduce((a,x,i)=>a+x*[.4,.3,.2,.1][i],0):null;
const labels={comparison:['版本测评','Version review'],development:['沟通与开发','Brief & development'],costs:['Token 与预算','Tokens & budget'],guide:['iPad 玩法','iPad play guide'],parents:['家长展示','For parents'],review:['测评与 Bug','Feedback & bugs']};
function header(title,sub){return `<header class="pageHeader"><a class="eyebrow" href="${link('hub')}">← ${P.name} / ${v(P.title)}</a><h1>${title}</h1><p>${sub}</p></header>`;}
function buildCard(b,detail=false){return `<article class="card modelcard" id="${esc(b.key)}"><img class="photo" src="${b.image}" alt="${esc(v(b.name))}" loading="lazy"><div class="cardBody"><span class="badge">${v(b.tag)}</span><h3>${v(b.name)}</h3><div class="modelID">${b.tool} · ${v(b.release)}</div><p class="buildIntro">${v(b.subtitle)}</p><p class="build-note"><b>${t('长处','Strength')}</b>${v(b.strength)}</p><p class="build-note limit"><b>${t('边界','Limit')}</b>${v(b.limit)}</p><div class="scores"><span><b>${b.tokens==null?'—':(b.tokens/1e6).toFixed(2)+'M'}</b>${b.tokens==null?t('历史用量未找回','Historical tokens unavailable'):'Token'}</span><span><b>≈ A$${m(b.aud)}</b>${t('该阶段工具估算','Stage tool estimate')}</span><span><b>☆☆☆☆☆</b>${t('AI 理据评分','AI reasoned rating')}</span></div>${detail?`<p>${v(b.detail||b.subtitle)}</p>`:''}<div class="actions"><a class="btn primary" href="${gameLink(b)}">${t('直接单人试玩','Play solo now')} ↗</a><a class="btn" href="${link('review')}&build=${b.key}">${t('写试玩记录','Write a playtest')} →</a></div></div></article>`;}
function downloads(){return `<section class="paper downloadBlock"><div><span class="eyebrow">HUB R6 / SOLO PACKAGE</span><h2>${t('这个作品，一份完整单机包','One work, one complete solo package')}</h2><p>${t('网页按钮直接试玩，不依赖老师电脑。电脑离线包包含当前单机分支、历史试玩版、独立 HUB、预算和学习记录；解压后按说明启动本机静态服务。','Play directly in the browser, without the teacher’s computer. The computer archive includes current solo branches, playable history, this HUB, its budget and learning record. Extract it and follow the local static-server instructions.')}</p></div><a class="btn primary" href="../downloads/r6-latest.zip" download>${t('下载本作品','Download this work')} ↓</a></section>`;}
function guide(){return header(v(labels.guide),t('家里打开链接就能玩，不要求老师电脑在线。','Open the link at home. The teacher’s computer does not need to be online.'))+`<section class="paper"><h2>${t('推荐横屏，双手操作','Landscape, with both hands')}</h2><p>${v(P.guide)}</p><div class="actions">${P.branches.filter(b=>b.path).map(b=>`<a class="btn primary" href="${gameLink(b)}">${v(b.name)} ↗</a>`).join('')}</div></section><div class="two"><section class="paper"><h2>${t('暂停与屏幕','Pause & display')}</h2><p>${t('左侧工具栏可以暂停与切换语言。切到其他页面时自动暂停，避免回来时已经失败。全屏是可选功能，Safari 不支持时仍可直接玩，也可“分享 → 添加到主屏幕”。','The left-side toolbar pauses and changes language. Leaving the page pauses play. Fullscreen is optional; play directly in Safari when unavailable, or use Share → Add to Home Screen.')}</p></section><section class="paper"><h2>${t('单机与存档','Solo play and saving')}</h2><p>${t('网页首次加载需要网络；开始后逻辑在当前设备运行，不需要游戏服务器。刷新读取本版本本机进度；战斗时请先结束战斗再切换语言。不提供云存档。电脑离线版另有 ZIP，iPad 不需要安装 Node.js。','Initial website loading needs a connection; game logic then runs on the device without a game server. Reloading reads this edition’s local progress; finish battles before changing language. No cloud saving is provided. Computer offline ZIPs are separate. iPad does not need Node.js.')}</p></section></div>${downloads()}`;}
function parents(){return header(t('孩子参与了什么，学到了什么','What the children contributed and learned'),t('课堂实际实践、工程知识和结构化表达放在一起；表达模板不是学生逐字原话。','Observed practice, engineering and structured expression together; templates are not verbatim student quotes.'))+`<section class="paper"><h2>${t('先让孩子带你玩一次','Let your child guide you')}</h2><p>${v(P.intro)}</p>${P.questions.map((x,i)=>`<div class="changeRow"><span class="changeNumber">${i+1}</span><h3>${v(x)}</h3></div>`).join('')}</section>${P.learning.map((x,i)=>`<section class="paper learning"><span class="eyebrow">LEARNING ${String(i+1).padStart(2,'0')}</span><h2>${v(x.title)}</h2><div class="two"><div><h3>${t('实际实践','Observed practice')}</h3><p>${v(x.practice)}</p><h3>${t('相关工程知识','Related engineering')}</h3><p>${v(x.knowledge)}</p></div><div><h3>${t('结构化表达模板','Expression pattern')}</h3><blockquote>${v(x.expression)}</blockquote><p class="fine">${v(x.level)}</p></div></div></section>`).join('')}<section class="paper"><h2>${t('R6 也是一个真实工程案例','R6 is also an engineering example')}</h2><p>${t('多人规则移到本机执行，说明“游戏规则”和“传输方式”可以分离。中文与英文共用同一份状态，暂停冻结逻辑时钟；版本、需求、预算与学习记录从一个作品入口接续。','Moving multiplayer rules onto the device demonstrates separation of game rules from transport. Both languages share state; pause freezes the simulation clock. Versions, requirements, budgets and learning continue from one project entrance.')}</p><p>${t('这是本轮代码实践的复盘，不等于已经在课堂教授或评估每个孩子掌握。','This describes this revision’s implementation; it is not a claim of classroom teaching or individual mastery.')}</p></section><div class="actions"><a class="btn primary" href="${link('review')}">${t('写下自己的试玩与学习','Write your playtest and learning')}</a><a class="btn" href="learning-record.json">${t('完整结构化记录','Complete structured record')}</a></div>`;}
function review(){return header(v(labels.review),t('问题可以复现，反馈才有用。','Useful feedback tells us how to reproduce the problem.'))+`<section class="paper"><h2>${t('本轮修复记录','This revision’s fixes')}</h2>${P.changes.map(([a,b],i)=>`<div class="changeRow"><span class="badge">R6-${i+1}</span><div><h3>${v(a)}</h3><p>${v(b)}</p></div></div>`).join('')}</section><section class="paper"><h2>${t('家庭试玩记录','Home playtest report')}</h2><label>${t('记录人','Reviewer')}<select id="reviewer">${P.people_names.map(x=>`<option>${x}</option>`).join('')}</select></label><label>${t('版本','Build')}<select id="buildChoice">${P.branches.filter(b=>b.path).map(b=>`<option value="${b.key}">${v(b.name)}</option>`).join('')}</select></label><label>${t('设备与浏览器','Device & browser')}<input id="device" placeholder="iPad / Safari"></label><label>${t('评分','Rating')}<select id="rating"><option value="">—</option>${[1,2,3,4,5].map(i=>`<option>${i}</option>`).join('')}</select></label><label>${t('重现步骤 → 期待结果 → 实际结果','Steps → expected → actual')}<textarea id="notes" rows="5"></textarea></label><div class="actions"><button class="btn primary" id="saveFeedback">${t('保存到本机','Save locally')}</button><button class="btn" id="exportFeedback">${t('导出 JSON','Export JSON')}</button><button class="btn" id="githubFeedback">${t('去 GitHub 提交','Open GitHub issue')}</button></div><p id="feedbackStatus" role="status"></p><p class="fine">${t('本机保存不是发送给老师。GitHub 按钮只打开提交页，由你确认发送；公开反馈不要包含孩子录音、联系方式或敏感个人信息。','Saving locally does not send a report to the teacher. GitHub opens a form for you to review and submit. Do not include student recordings, contact details or sensitive personal information in a public issue.')}</p></section>`;}
function percent(){return Math.round(100*P.milestones.filter(x=>x.status==='complete').length/P.milestones.length);}
function bar(value,label){return `<div class="meter" role="progressbar" aria-label="${esc(label)}" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${value}"><i style="width:${Math.max(0,Math.min(100,value))}%"></i></div>`;}
function whole(x){return Math.round(x).toLocaleString('en-AU');}
function range(xs,suffix=''){return xs.map(whole).join('–')+suffix;}
function budget(){const used=P.cost.api_equivalent_aud,ratio=used/P.budget*100,e=P.efficiency,h=P.human;return `<section class="project-dashboard" aria-label="${t('项目投入与进度','Project investment and progress')}"><a class="metric metric-budget" href="${link('costs')}"><span class="metric-label">${t('预算估算','Estimated budget used')}</span><strong>A$${m(used)} <i>/ ${P.budget}</i></strong>${bar(+ratio.toFixed(1),t('预算使用率','Budget used'))}<div class="metric-caption"><b>${ratio.toFixed(1)}%</b><span>${t('工具总估算 / 总池','estimated tools / pool')}</span></div></a><a class="metric metric-progress" href="${link('development')}#stage-map"><span class="metric-label">${t('总体阶段进度','Delivery progress')}</span><strong>${percent()}<i>%</i><small>6 / 7</small></strong>${bar(percent(),t('总体阶段进度','Delivery progress'))}<div class="metric-caption"><b>${t('待实机与确认','Awaiting final playtest')}</b></div></a><a class="metric metric-human" href="${link('costs')}#human"><span class="metric-label">${t('人工成本估算','Manual rebuild estimate')}</span><strong>≈ A$${whole(h.aud_mid)}</strong><div class="metric-bottom"><b>${range(h.hours_range,' h')}</b><span>${t('当前完整交付 · 人工估算','current package · estimated labour')}</span></div></a><a class="metric metric-efficiency" href="${link('costs')}#efficiency"><span class="metric-label">${t('课堂原型效率对照','Classroom prototype efficiency')}</span><div class="ratio-pair"><div><strong>≈${whole(e.time_ratio_mid)}<i>×</i></strong><small>${t('时间','Time')}</small></div><div><strong>≈${whole(e.cost_ratio_mid)}<i>×</i></strong><small>${t('工具成本','Tool cost')}</small></div></div><span class="metric-foot">${t('人工估算 ÷ 同阶段估算','Manual estimate ÷ same-stage estimate')} ↗</span></a></section><details class="metric-method"><summary>${t('数字怎么来的','How these numbers are calculated')}</summary><p>${v(P.metric_scope_note)} ${v(P.cost_note)}${t("。",". ")} ${v(P.milestone_note)}</p></details>`;}
function stageMap(){return `<section class="stage-panel" id="stage-map"><div class="sectionHead"><div><span class="eyebrow">PROJECT MILESTONES</span><h2>${t('做到哪一步','Where the project stands')}</h2></div><div class="stage-score"><b>${percent()}%</b><small>${v(P.progress_scope)}</small></div></div><div class="stage-line">${P.milestones.map((x,i)=>`<div class="stage ${x.status}"><span class="stage-node">${x.status==='complete'?'✓':String(i+1).padStart(2,'0')}</span><b>${v(x.name)}</b><small>${v(P.milestone_evidence[i])}</small></div>`).join('')}</div><p class="next-inline">${v(P.progress_next)}</p></section>`;}
function routeMap(){return `<section class="route-panel merge-route"><div class="sectionHead"><div><span class="eyebrow">FROM BRIEF TO BUILD</span><h2>${t('一张图看清开发路线','The development route at a glance')}</h2></div><span class="fine">${t('实线＝已做 · 虚线＝待确认','Solid = delivered · dashed = pending')}</span></div><div class="route-root"><small>01 / ${t('作品的起点','Project origin')}</small><h3>${v(P.route_title)}</h3><p>${v(P.route_start)}</p></div><div class="route-lanes">${P.flow_lanes.map(x=>`<a class="route-lane retained" href="${link('development')}#event-${x.id}"><div><span class="route-badge">${v(x.name)}</span><b>${t('保留','Retained')}</b></div><p>${v(x.desc)}</p><small>${t('查看需求与实现','Requirements and implementation')} →</small></a>`).join('')}</div><div class="route-result proposed"><span>${t('下一关 · 实机与教师确认','Next gate · device play and teacher sign-off')}</span><h3>${v(P.next_title)}</h3><p>${v(P.next_scope)}</p></div></section>`;}
function home(){const current=P.branches.filter(b=>!b.legacy),old=P.branches.filter(b=>b.legacy);const entries=[['comparison','01',t('版本对照与变化','Build comparison & changes'),t('最新单机版优先，旧版另区；保留原始开发证据。','Current solo builds first, history separately; original evidence preserved.')],['development','02',t('完整沟通与开发历程','Full discussion & development'),t('从上周创意、原版生产、试玩反馈到当前交付。','From initial ideas and production to playtesting and this release.')],['costs','03',t('完整预算与效率','Complete budget & efficiency'),t('历史＋新开发＋整理＋本轮适配，统一估算。','One estimate for history, new builds, recovery and adaptation.')],['guide','04',t('单机试玩指南','Solo play guide'),t('双语、暂停、返回 HUB 与本机进度。','Bilingual play, pause, return to HUB and local progress.')],['parents','05',t('课堂实践与学习记录','Classroom practice & learning'),t('大家提出什么、如何验证、学到了什么。','Requirements, verification, engineering and expression.')],['review','06',t('我的试玩与 Bug','My playtest & bugs'),t('按人保存：设备、操作、预期、实际与改进。','Separate drafts: device, action, expectation, result and improvement.')]];return budget()+`<section class="hero"><img class="cover" src="${P.hero}" alt="${esc(v(P.title))}"><div class="heroContent"><span class="eyebrow">${P.name} / CLASSROOM STUDIO</span><h1>${v(P.heroTitle)}</h1><p>${v(P.intro)}</p><div class="actions"><a class="btn primary" href="${P.featured_play?P.featured_play.url+'?lang='+(L?'en':'zh-CN'):gameLink(current[0])}">${P.featured_play?v(P.featured_play.label):t('试玩最新单机版','Play the latest solo build')} ↗</a>${P.featured_play?`<a class="btn" data-featured-solo href="${gameLink(current[0])}">${t('Opus 单人试玩','Opus solo preview')} ↗</a>`:''}<a class="btn" href="${link('development')}">${t('看完整开发过程','See the full development')} →</a></div></div><span class="heroBadge">HUB r6 · ${t('MVP 待最终测试','MVP final test pending')}</span></section><div class="decision-panel"><span class="eyebrow">LATEST RELEASE · R6</span><p>${v(P.decision)}</p></div><div class="sectionHead" id="builds"><div><span class="eyebrow">CURRENT PLAYABLE BUILDS</span><h2>${t('最新版 · 直接单人试玩','Latest builds · play solo now')}</h2></div><a class="text-link" href="${link('comparison')}">${t('展开版本对照','Compare the versions')} ↗</a></div><div class="two builds">${current.map(b=>buildCard(b)).join('')}</div>${stageMap()}${routeMap()}<div class="sectionHead"><div><span class="eyebrow">PROJECT RECORDS</span><h2>${t('看作品，也看做选择的过程','The game—and the decisions behind it')}</h2></div></div><div class="cards">${entries.map(([page,no,title,desc])=>`<a class="card cardLink" href="${link(page)}"><div class="cardBody"><div class="icon">${no}</div><h3>${title}</h3><p>${desc}</p><div class="arrow">${t('打开','Open')} <span>↗</span></div></div></a>`).join('')}</div><section class="history-zone" id="history"><div class="sectionHead"><div><span class="eyebrow">ARCHIVE · NOT THE LATEST RELEASE</span><h2>${t('历史版本 · 单独对照','Historical builds · separate comparison')}</h2><p>${t('历史试玩也有双语和返回当前 HUB。原始未改源码保留在 Git 历史，不再跳进旧 HUB。','Historical previews have language and return controls too. Original sources remain in Git history; no old HUB detour.')}</p></div></div><div class="two builds">${old.map(b=>buildCard(b)).join('')}</div><details><summary>${t('修复前与初始快照','Pre-fix and initial snapshots')}</summary><p>${v(P.snapshot_note)}</p></details></section>${downloads()}`;}
function comparison(){return header(t('版本对照<br>先看最新，再看历史','Build comparison<br>Current first, history separately'),v(P.decision))+`<div class="sectionHead"><h2>${t('当前单机分支','Current solo branches')}</h2></div><div class="two builds">${P.branches.filter(b=>!b.legacy).map(b=>buildCard(b,true)).join('')}</div><section class="paper"><h2>${t('本次 R6 修订','R6 changes')}</h2>${P.changes.map(([a,b],i)=>`<div class="changeRow"><span class="changeNumber">${i+1}</span><div><h3>${v(a)}</h3><p>${v(b)}</p></div></div>`).join('')}</section><section class="history-zone"><h2>${t('历史对照','Historical comparison')}</h2><div class="two builds">${P.branches.filter(b=>b.legacy).map(b=>buildCard(b,true)).join('')}</div></section><section class="paper"><h2>${t('验收范围','Acceptance scope')}</h2><p>${t('HUB 版式、预算一致性、双语切换、单机运行、暂停与返回分别测试。自动浏览器验证不等于实体 iPad 的完整长流程；原始版本的失败记录仍保留。','Layout, budget consistency, language switching, solo runtime, pause and return are tested separately. Browser automation is not a full physical-iPad playthrough; original failed records remain.')}</p><a href="../shared/hub-r6/qa/results.json">${t('打开本次验收记录','Open this acceptance record')}</a></section>`;}
function when(s){if(!L)return s;return s.replace('课堂','class').replace('Claude 分支','Claude branch').replace('Astra 分支','Astra branch').replace('课后','After class').replace('对照与家庭适配','Review & home adaptation').replace('家庭交付','Home delivery').replace('下一步','Next').replace('待验证','Pending').replace('手感与平衡','Controls & balance').replace('家庭版本','Home edition');}
function development(){const k=P.id==='kehan';return header(t('从课堂想法<br>到今天的作品','From a classroom idea<br>to the current build'),v(P.route_start))+routeMap()+stageMap()+`<section class="paper brief-focus"><span class="eyebrow">CLASSROOM PRIORITIES</span><h2>${t('对话里真正决定作品的要点','The discussion points that shaped the game')}</h2><div class="brief-grid">${P.requirements.slice(0,4).map(([a,b],i)=>`<div><small>0${i+1}</small><h3>${v(a)}</h3><p>${v(b)}</p></div>`).join('')}</div><p class="fine">${t('内容来自保存的课堂 brief、用户反馈与开发记录。对话重点为整理摘要，未将 brief 中的假想台词冒充学生原话。','Summarized from saved briefs, user feedback and development records. Hypothetical dialogue within a brief is not represented as actual student speech.')}</p></section><div class="sectionHead"><div><span class="eyebrow">COMPLETE DEVELOPMENT JOURNEY</span><h2>${t('关键节点：需求 → 工具 → 结果','Key nodes: requirement → tools → result')}</h2></div><span class="fine">${t('时间均为悉尼时间','All times are Sydney time')}</span></div><div class="journey">${P.journey.map((e,i)=>`<article class="journey-event ${e.status}" id="event-${e.id}"><div class="journey-marker">${String(i+1).padStart(2,'0')}</div><div class="journey-body"><div class="journey-meta"><time>${when(e.date)}</time><span>${e.status==='rejected'?t('已弃用','Rejected'):e.status==='planned'?t('下一轮提案','Next-round proposal'):t('已有记录','Recorded')}</span></div><h2>${v(e.title)}</h2><p class="event-summary">${v(e.summary)}</p><div class="event-outcome"><small>${t('带来的变化','Outcome')}</small><p>${v(e.result)}</p></div><details ${i<2?'open':''}><summary>${t('对话重点、工具方向与技术选择','Key requirements, tool direction and technical choices')}</summary><div class="event-details"><div><h3>${t('对话 / Brief','Discussion / brief')}</h3><p>${v(e.brief)}</p></div><div><h3>${t('工具调用方向','Tool workflow')}</h3><p>${v(e.tool)}</p></div><div><h3>${t('技术栈与实现','Stack & implementation')}</h3><p>${v(e.tech)}</p></div></div></details><a class="evidence-ref" href="#sources">${t('依据','Evidence')}: ${esc(e.source)}</a></div></article>`).join('')}</div><section class="paper" id="sources"><h2>${t('记录依据','Evidence behind the route')}</h2><div class="source-grid">${P.sources.map(x=>`<div><code>${x.id}</code><h3>${v(x.label)}</h3>${x.note?`<p>${v(x.note)}</p>`:''}</div>`).join('')}</div><p class="fine">${t('公开页提供脱敏摘要，不上传原始会话、录音、家庭网络地址。历史验收与本轮 R6 核验分别标识，不把旧测试算成本轮新测试。','This page provides sanitized summaries, not raw sessions, recordings or home-network addresses. Historical and current R6 checks are distinguished.')}</p><a class="text-link" href="learning-record.json">${t('查看结构化记录','Open structured evidence')} ↗</a></section>`;}
function humanSection(){const h=P.human;return `<section class="paper" id="human"><span class="eyebrow">CURRENT PACKAGE · MANUAL REBUILD</span><h2>${t('同样的当前交付，人工重建需要什么','What a manual rebuild of this package involves')}</h2><div class="human-summary"><div><small>${t('工时估算','Estimated hours')}</small><strong>${range(h.hours_range)} <i>h</i></strong></div><div><small>${t('人工费用区间','Estimated labour range')}</small><strong>A$${range(h.aud_range)}</strong></div><div><small>${t('中点情景','Midpoint scenario')}</small><strong>A$${whole(h.aud_mid)}</strong></div></div><p>${v(h.scope)}${t("。",". ")} ${v(P.rate_note)}</p><div class="workbreakdown">${P.human_tasks.map(x=>`<div><span>${v(x.task)}</span><div class="workbar"><i style="width:${x.range[1]/Math.max(...P.human_tasks.map(y=>y.range[1]))*100}%"></i></div><b>${x.range.join('–')} h</b></div>`).join('')}</div><p class="fine">${t('这是按工作项拆解的规划估算，不是实际已花的人工，也不是成品销售价。范围包含现有网页交付，不包含未实现的融合版或未验收的跨设备联机扩展。','A task-based planning estimate, not actual labour spent or sale value. It covers the current web delivery, not an unbuilt merge or unverified networking extension.')}</p></section>`;}
function efficiencySection(){const e=P.efficiency;return `<section class="paper" id="efficiency"><span class="eyebrow">SAME STAGE · EXPLICIT BASIS</span><h2>${t('时间和工具成本，相差多少','How time and tool cost compare')}</h2><p>${v(P.prototype_estimate_basis)}</p><div class="two efficiency-cards"><article><h3>${t('时间效率','Time efficiency')}</h3><strong>≈ ${whole(e.time_ratio_mid)}×</strong><div class="compare-line"><span>${t('人工原型估算','Manual prototype estimate')}</span><b>${e.manual_hours_range.join('–')} h</b></div><div class="compare-line"><span>${t('已记录开发窗口','Recorded development window')}</span><b>${e.elapsed_display}</b></div><p>${t('区间','Range')}: ${range(e.time_ratio_range)}×</p><code>${e.manual_hours_mid} h ÷ (${e.elapsed_seconds} s / 3600) = ${e.time_ratio_mid.toFixed(1)}×</code></article><article><h3>${t('工具成本对照','Tool-cost comparison')}</h3><strong>≈ ${whole(e.cost_ratio_mid)}×</strong><div class="compare-line"><span>${t('人工原型估算','Manual prototype estimate')}</span><b>A$${whole(e.manual_aud_mid)}</b></div><div class="compare-line"><span>${t('工具费率折算估计','Estimated tool equivalent')}</span><b>A$${m(e.tool_cost_aud)}</b></div><p>${t('区间','Range')}: ${range(e.cost_ratio_range)}×</p><code>A$${m(e.manual_aud_mid)} ÷ A$${m(e.tool_cost_aud)} ≈ ${e.cost_ratio_mid.toFixed(1)}×</code></article></div><div class="notice">${v(e.note)}</div><p class="fine">${t('当前完整项目的时间/全成本效率不报倍数：课后主控与教师人工没有完整计时计费，不能把它们当成零，也不能把这张表的倍数套到全项目。','No all-project time or all-in cost multiplier is claimed: post-class controller work and teacher labour are not fully metered. They are not zero, and these prototype ratios cannot be applied to the entire project.')}</p></section>`;}
function costs(){const c=P.cost;return header(t('完整预算，不留空白','A complete budget, not blank cells'),t('以工具/API 等值估算统一记账，不是额外订阅扣款或实付发票。所有历史投入直接合并于此，不再跳转旧 HUB。','One tool/API-equivalent estimate, not extra subscription charges or a paid invoice. Historical work is consolidated here without an old-HUB detour.'))+budget()+`<section class="paper"><h2>${t('从最初制作到当前交付','From first production to this delivery')}</h2><div class="human-summary"><div><small>${t('总估算','Total estimate')}</small><strong>A$${m(c.api_equivalent_aud)}</strong></div><div><small>${t('估算范围','Estimated range')}</small><strong>A$${m(c.range[0])}–${m(c.range[1])}</strong></div><div><small>${t('预算余额（中点）','Remaining budget (central estimate)')}</small><strong>A$${m(P.budget-c.api_equivalent_aud)}</strong></div></div><div class="tableWrap"><table><thead><tr><th>${t('阶段','Stage')}</th><th>${t('估算 AUD','Estimated AUD')}</th><th>${t('范围 AUD','Range AUD')}</th><th>${t('依据与口径','Evidence and basis')}</th></tr></thead><tbody>${c.items.map(x=>`<tr><td><b>${v(x.title)}</b></td><td>${m(x.aud)}</td><td>${m(x.range[0])}–${m(x.range[1])}</td><td>${v(x.note)}</td></tr>`).join('')}<tr><td><b>${t('合计','Total')}</b></td><td><b>${m(c.api_equivalent_aud)}</b></td><td>${m(c.range[0])}–${m(c.range[1])}</td><td>${t('同一数据源汇总，无重复叠加','Summed from one ledger, without double-counting')}</td></tr></tbody></table></div><details open><summary>${t('估算方法与历史回收','Estimation and historical recovery')}</summary><p>${v(P.cost_note)}</p><p>${v(c.method)}</p><p>${t('已回收 Token 的开发用量按仓库 9 月 22 日费率/汇率快照估算；不把历史快照声称为今日实时报价。未计量的历史、HUB 整理和本轮适配用有界工作量预估，已经纳入总额而不是算零。','Recovered usage is valued using the repository’s 22 September price/FX assumptions, not claimed as live rates. Unmetered history, HUB recovery and this adaptation use bounded workload estimates and are included, not treated as zero.')}</p><p>${t('此预算池用于作品制作工具成本。教师授课报酬、订阅固定月费和税费不与 API 等值重复混算；当前作品的人工重建估值另表列出。','The project pool covers production-tool cost. Teaching wages, fixed subscriptions and tax are not mixed or double-counted with API equivalents. A manual rebuild valuation is shown separately.')}</p></details><a class="btn" href="budget.json" download>${t('下载完整预算账本','Download complete budget')}</a></section>${humanSection()}${efficiencySection()}`;}
function setup(){if(Q==='review'){let key='studio-r6-feedback-'+P.id+'-'+document.getElementById('reviewer').value;document.getElementById('reviewer').onchange=()=>{key='studio-r6-feedback-'+P.id+'-'+document.getElementById('reviewer').value;let x={};try{x=JSON.parse(localStorage.getItem(key)||'{}')}catch{};for(const f of ['buildChoice','device','rating','notes'])document.getElementById(f).value=x[f]||'';};try{const saved=JSON.parse(localStorage.getItem(key)||'{}');for(const id of ['buildChoice','device','rating','notes'])if(saved[id]!=null)document.getElementById(id).value=saved[id];}catch{}const data=()=>({project:P.id,version:D.release,createdAt:new Date().toISOString(),...Object.fromEntries(['buildChoice','device','rating','notes'].map(id=>[id,document.getElementById(id).value])),reviewer:document.getElementById('reviewer').value,status:'LOCAL_DRAFT'});document.getElementById('saveFeedback').onclick=()=>{localStorage.setItem(key,JSON.stringify(data()));document.getElementById('feedbackStatus').textContent=t('已保存到当前浏览器，未发送。','Saved in this browser; not sent.');};document.getElementById('exportFeedback').onclick=()=>{const u=URL.createObjectURL(new Blob([JSON.stringify(data(),null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=u;a.download=P.id+'-r6-feedback.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);};document.getElementById('githubFeedback').onclick=()=>{const x=data(),body='Build: '+x.buildChoice+'\nVersion: '+x.version+'\nDevice: '+x.device+'\nRating: '+x.rating+'\n\n'+x.notes;window.open('https://github.com/sydneygemstone-sudo/hiro-brynne-zombie-dungeon/issues/new?title='+encodeURIComponent('['+P.id+' '+D.release+'] Playtest')+'&body='+encodeURIComponent(body),'_blank','noopener');};}}

// R6_FINAL_PRESENTATION_20260925 — target-language button, not a dropdown.
function languageButton(){return `<button id="language" class="hub-language-toggle" type="button" lang="${L?'zh-CN':'en'}" aria-label="${L?'切换为中文':'Switch to English'}">${L?'中文':'English'}</button>`;}
function bindLanguageButton(){const button=document.getElementById('language');if(!button)return;button.onclick=()=>{
 const y=window.scrollY,values=[...app.querySelectorAll('input[id],select[id],textarea[id]')].map(x=>({id:x.id,value:x.value,checked:x.checked}));
 L=L?0:1;const url=new URL(location.href);url.searchParams.set('lang',L?'en':'zh-CN');history.replaceState(null,'',url.pathname+url.search+url.hash);document.documentElement.lang=L?'en':'zh-CN';
 if(P){render();const reviewer=values.find(x=>x.id==='reviewer');if(reviewer&&document.getElementById('reviewer')){document.getElementById('reviewer').value=reviewer.value;document.getElementById('reviewer').dispatchEvent(new Event('change'));}for(const x of values){const field=document.getElementById(x.id);if(field){field.value=x.value;if('checked'in field)field.checked=x.checked;}}requestAnimationFrame(()=>{window.scrollTo(0,y);document.getElementById('language')?.focus({preventScroll:true});});}
 else{button.outerHTML=languageButton();bindLanguageButton();}
};}
function render(){document.body.className=P.theme;document.documentElement.lang=L?'en':'zh-CN';document.title=v(P.title)+' · '+(Q==='hub'?'HUB':v(labels[Q]));document.querySelector('#nav').innerHTML=`<a class="brand" href="${link('hub')}">GEMSTONE <span>/ ${t('作品 HUB','PROJECT HUB')}</span></a><div class="navright"><a href="${link('hub')}">HUB</a><a href="${link('comparison')}">${t('测评','Review')}</a>${languageButton()}</div>`;app.innerHTML=({hub:home,comparison,development,costs,guide,parents,review}[Q]||home)();document.querySelector('#footer').innerHTML=`<span>${P.name} · ${D.release} · ${t('英语 / 简体中文','English / Simplified Chinese')}</span><p>${t('公开内容为作品摘要与汇总成本；原始课堂会话、音频和私密记录不公开。评分针对作品，不针对孩子。','Public content includes project summaries and aggregate costs, not raw classroom conversations, audio or private records. Ratings describe artifacts, not children.')}</p>`;bindLanguageButton();setup();}
function historicalRecords(){const h=P.historical_context;return `<section class="paper"><span class="eyebrow">IMPORTED HISTORY · NO OLD HUB DETOUR</span><h2>${t('早期资料已合并到这里','Earlier records are consolidated here')}</h2><p>${t('以下保留当时的需求、问题与验收口径；历史状态不是本轮新验收结论。','Earlier requirements, issues and test scopes are preserved below; historical statuses are not this revision’s verdict.')}</p>${h.requirements?`<details><summary>${t('最早的四项作品需求','The four original requirements')}</summary><div class="brief-grid">${h.requirements.map(([a,b])=>`<div><h3>${v(a)}</h3><p>${v(b)}</p></div>`).join('')}</div></details>`:''}${h.tests?`<details><summary>${t('上周的完整测试记录','Earlier complete test record')}</summary>${h.tests.map(([a,b,c])=>`<div class="changeRow"><div><h3>${v(a)}</h3><p>${v(b)}</p><p class="fine">${v(c)}</p></div></div>`).join('')}</details>`:''}<a class="btn" href="historical-context.json">${t('查看合并的全部历史数据','All imported historical data')} ↗</a></section>`;}
function recordedIssues(){return `<section class="paper"><h2>${t('课堂问题与修复跟踪','Classroom issues and follow-up')}</h2>${P.recorded_issues.map(x=>`<div class="changeRow"><span class="badge">${esc(x[0])}</span><div><h3>${v(x[1])}</h3><p>${v(x[2])}</p><small>${v(x[3])} · ${t('原记录状态保留，R6 验收另列','Original status retained; R6 acceptance is separate')}</small></div></div>`).join('')}${P.historical_context.issues?`<details><summary>${t('上周已记录的问题','Issues recorded in the earlier HUB')}</summary>${P.historical_context.issues.map(x=>`<h3>${esc(x[0])} · ${v(x[2])}</h3><p>${v(x[3])}</p>`).join('')}</details>`:''}</section>`;}
const originalDevelopment=development;development=()=>originalDevelopment()+historicalRecords();const originalReview=review;review=()=>originalReview()+recordedIssues();

// LIFECYCLE_OVERLAY_BEGIN
// Scoped R6 lifecycle layer. Runs inside the existing studio renderer closure.
const lp=x=>Number(x).toFixed(1).replace(/\.0$/,''),phaseDone=p=>p.gates.filter(g=>g.status==='complete').length,phasePct=p=>phaseDone(p)/p.gates.length*100,overallPct=()=>P.lifecycle.phases.reduce((s,p)=>s+phasePct(p),0)/P.lifecycle.phases.length;
function lEvidence(ids){return ids.map(id=>{const s=P.governance_sources[id];return s?`<a class="evidence-chip" href="${esc(s.href)}" target="_blank" rel="noopener">${esc(id)} ↗</a>`:`<span>${esc(id)}</span>`;}).join(' ');}
function aiStars(r,linked=true){const inner=`<span class="ai-star-glyph" aria-hidden="true"><span>☆☆☆☆☆</span><span class="ai-star-fill" style="width:${r.stars/5*100}%">★★★★★</span></span><strong>${lp(r.stars)}<small>/5</small></strong><span>${t('AI 理据评分','AI reasoned rating')}</span>`;return linked?`<a class="ai-rating" data-ai-rating="${esc(r.id)}" aria-label="${t('AI理据评分','AI reasoned rating')} ${lp(r.stars)}/5" href="${link('comparison')}#ai-${esc(r.id)}">${inner}</a>`:`<div class="ai-rating">${inner}</div>`;}
function aiFeatured(){const id=P.id==='trio'?'opus-online':'martin-v2',r=P.ai_reviews.reviews.find(x=>x.id===id);return `<section class="ai-featured" aria-label="${t('当前主线AI评审','Featured mainline AI review')}"><div><span class="eyebrow">AI REVIEW · MVP QUALITY</span><h3>${v(r.name)}</h3><p>${v(r.strength)}</p></div><div>${aiStars(r)}<p class="fine">${t('评价MVP质量，不等于完整资产或商业发布就绪。','MVP quality, not full-asset or commercial readiness.')}</p></div></section>`;}
function lifecycleCard(p,i){const done=phaseDone(p),percent=phasePct(p);return `<article class="lifecycle-phase ${p.state}" data-phase="${p.id}"><div class="phase-header"><span class="phase-number">0${i+1}</span><div><span class="badge">${p.state==='active'?t('当前阶段','Current phase'):t('后续阶段 · 未启动验收','Later phase · not yet accepted')}</span><h3>${v(p.name)}</h3></div></div><div class="phase-count"><strong>${lp(percent)}%</strong><span>${done}/${p.gates.length} ${t('验收项','gates')}</span></div>${bar(+percent.toFixed(1),v(p.name))}<p>${v(p.goal)}</p><p class="phase-exit"><b>${t('阶段出口','Exit gate')}</b><br>${v(p.exit)}</p><details ${p.state==='active'&&Q==='development'?'open':''}><summary>${t('查看阶段内步骤','Show phase steps')} · ${done}/${p.gates.length}</summary><ol class="phase-gates">${p.gates.map((g,j)=>`<li class="${g.status}" data-gate="${g.id}"><span class="gate-icon">${g.status==='complete'?'✓':g.status==='pending'?'◷':j+1}</span><div><b>${v(g.title)}</b><p>${v(g.deliverable)}</p>${lEvidence(g.evidence)}</div></li>`).join('')}</ol></details></article>`;}
function lifecyclePanel(){return `<section class="lifecycle-panel" id="lifecycle"><span id="stage-map"></span><div class="sectionHead"><div><span class="eyebrow">THREE-PHASE PRODUCT LIFECYCLE</span><h2>${t('核心玩法、完整资产、正式发布：分三阶段推进','Core gameplay, full assets, formal release: three distinct phases')}</h2></div><div class="lifecycle-total"><strong data-overall>${lp(overallPct())}%</strong><span>${t('三阶段总进度','Three-phase overall')}</span></div></div>${bar(+overallPct().toFixed(1),t('三阶段里程碑总完成率','Overall three-phase milestone completion'))}<p class="lifecycle-position">${t('当前：第一阶段 MVP 核心玩法 · 6/7，距离定稿只差最终测试。','Current: phase 1, core-gameplay MVP · 6/7; final testing remains before freeze.')}</p><div class="lifecycle-grid">${P.lifecycle.phases.map(lifecycleCard).join('')}</div><details class="metric-method"><summary>${t('总进度的算法与边界','Overall calculation and scope')}</summary><p>${v(P.lifecycle.formula)}</p><p>${v(P.lifecycle.coverage_note)}</p><p>${t('阶段二、三在本轮只定义工作与验收边界，不擅自开始生产、商店上架或改变预算。长期运营按上线后的运行指标持续管理。','Phases 2/3 are defined here, not silently started, listed in stores or added to the budget. Ongoing operations use post-launch service metrics.')}</p><p class="formula">(6 ÷ 7 + 0 ÷ 8 + 0 ÷ 6) ÷ 3 = ${lp(overallPct())}%</p></details><div class="actions"><a class="btn" href="lifecycle.json">${t('查看三阶段与所有验收项','Three phases and all gates')} ↗</a><a class="btn" href="lifecycle-flow-${L?'en':'zh'}.svg" target="_blank" rel="noopener">${t('打开三阶段总览图','Open lifecycle diagram')} ↗</a></div></section>`;}
function lineageGraph(g){return `<article class="lineage-graph" id="graph-${g.id}"><div class="sectionHead"><div><h3>${v(g.title)}</h3><p>${v(g.summary)}</p></div></div><p class="fine">${t('手机可横向滑动图；也可打开大图或展开逐条箭头说明。','On a phone, scroll the diagram sideways, open it full size or expand the edge-by-edge explanation.')}</p><div class="graph-scroll" role="region" tabindex="0" aria-label="${v(g.title)}"><img class="mermaid-diagram" data-lineage="${g.id}" src="lineage-${g.id}-${L?'en':'zh'}.svg?v=lifecycle-1" alt="${esc(v(g.summary))}" loading="lazy"></div><div class="actions"><a class="btn" href="lineage-${g.id}-${L?'en':'zh'}.svg" target="_blank" rel="noopener">${t('打开大图','Open full diagram')} ↗</a><a class="btn" href="lineage-${g.id}-${L?'en':'zh'}.mmd" download>${t('Mermaid 源文件','Mermaid source')} ↓</a></div><details><summary>${t('逐条核对箭头含义与来源','Inspect each edge and its evidence')}</summary><div class="lineage-edge-list">${g.edges.map(x=>{const a=g.nodes.find(n=>n.id===x.source),b=g.nodes.find(n=>n.id===x.target);return `<article><span class="badge edge-${x.type}">${v(P.version_lineage.edge_types[x.type])}</span><h4>${v(a.title).replaceAll('\n',' · ')} → ${v(b.title).replaceAll('\n',' · ')}</h4><p>${v(x.reason)}</p>${lEvidence(x.evidence)}</article>`;}).join('')}</div></details><details><summary>${t('节点说明：版本、历史记录与待办的区别','Node detail: versions, historical notes and pending work')}</summary>${g.nodes.map(x=>`<div class="graph-node-note"><b>${v(x.title).replaceAll('\n',' · ')}</b><p>${v(x.detail)}</p>${lEvidence(x.evidence)}</div>`).join('')}</details></article>`;}
function lineagePanel(){const gs=P.version_lineage.graphs;return `<section class="route-panel real-lineage" id="version-lineage"><div class="sectionHead"><div><span class="eyebrow">VERSION DIVERGENCE · REPAIR · CONVERGENCE</span><h2>${t('多版本怎样发散、大修，再选择主线','How versions diverge, undergo repair and converge by selection')}</h2></div></div><div class="edge-legend"><span>${t('实线：实现/适配','Solid: implementation/adaptation')}</span><span>${t('橙线：同分支大修','Orange: in-branch major repair')}</span><span>${t('虚线：需求/评审/待办（看箭头文字）','Dashed: requirements/review/pending (read label)')}</span><span>${t('粗绿线：主线选择，不是源码融合','Thick green: mainline selection, not source merge')}</span></div>${lineageGraph(gs[0])}<details class="repair-fold" ${Q==='development'?'open':''}><summary>${t('展开大修路径：为什么改、怎么改、证明了什么','Major repair paths: why, how, and what was proven')}</summary>${lineageGraph(gs[1])}</details><p class="fine">${v(P.version_lineage.no_merge_statement)}</p><a class="text-link" href="version-lineage.json">${t('读取全部节点、边与证据','All nodes, edges and evidence')} ↗</a></section>`;}
function aiReviewPanel(){const model=P.ai_reviews;return `<section class="paper ai-review-panel" id="ai-reviews"><span class="eyebrow">AI-AUTHORED · EVIDENCE-BASED · MVP SCOPE</span><h2>${t('星级由 AI 给理据，不等人来打星','AI ratings with reasons, not a human-rating placeholder')}</h2><p>${t('这是 AI 对当前版本的阶段性判断，不是算法测试自动算出的事实，也不汇总玩家打分。每个分数对应下面的维度、依据、风险与下一项验证。','These are authored AI judgments about each version, not facts automatically computed by test scripts or aggregates of player votes. Each score has dimensions, evidence, risks and a next verification step.')}</p><div class="rubric-grid">${model.rubric.map(r=>`<div><b>${v(r.name)}</b><strong>${r.max}%</strong></div>`).join('')}</div><p class="fine">${t('五项满分合计100；星级 = 总分 ÷ 20，保留一位小数。评分仅衡量 MVP 质量，与三阶段完成度和平台发行就绪度分开。','The five dimensions total 100; stars = total / 20, to one decimal. Ratings assess MVP quality separately from lifecycle completion and release readiness.')}</p>${model.reviews.map(r=>`<article class="ai-review-detail" id="ai-${r.id}" data-ai-review="${r.id}"><div class="sectionHead"><div><span class="badge">AI · ChatGPT · ${t('基于记录的评审','record-based review')}</span><h3>${v(r.name)}</h3></div>${aiStars(r,false)}</div><div class="tableWrap"><table><thead><tr><th>${t('维度','Dimension')}</th><th>${t('得分','Points')}</th><th>${t('判断理由','Reason')}</th></tr></thead><tbody>${model.rubric.map((d,i)=>`<tr><td>${v(d.name)}</td><td>${r.points[i]}/${d.max}</td><td>${v(r.reasons[i])}</td></tr>`).join('')}<tr><th>${t('总分','Total')}</th><th>${r.total}/100</th><td>${t('AI推断性评价；测试只证明其记录的范围。','An AI evaluative judgment; tests prove only their recorded scope.')}</td></tr></tbody></table></div><div class="two"><div><h4>${t('主要长处','Strength')}</h4><p>${v(r.strength)}</p><h4>${t('不能忽略的缺口','Important gap')}</h4><p>${v(r.risk)}</p></div><div><h4>${t('下一项能改变评分的验证','Next check that can change the rating')}</h4><p>${v(r.next_test)}</p><h4>${t('引用的依据','Evidence used')}</h4>${lEvidence(r.evidence)}</div></div></article>`).join('')}<p class="fine">${t('未独立恢复的早期 Write 或修复前片段不虚构成完整发行版，也不分配无依据的星级；它们留在版本图与历史档案。','An unrecovered early Write or partial pre-fix snapshot is not invented into a complete release or given an unsupported rating; it remains in lineage/history.')}</p><a class="btn" href="ai-reviews.json">${t('查看评分原始数据与依据指纹','Rating data and evidence fingerprints')} ↗</a></section>`;}
const lifecycleNativeBudget=budget;budget=()=>{let html=lifecycleNativeBudget();const total=overallPct(),mvp=phasePct(P.lifecycle.phases[0]);const card=`<a class="metric metric-progress" href="${link('development')}#lifecycle"><span class="metric-label">${t('三阶段总进度','Three-phase overall')}</span><strong>${lp(total)}<i>%</i></strong>${bar(+total.toFixed(1),t('三阶段总进度','Three-phase overall'))}<div class="metric-caption"><b>${t('当前：MVP','Current: MVP')} ${lp(mvp)}%</b><span>${t('第一阶段 6/7 · 非全产品6/7','Phase 1: 6/7, not the whole product')}</span></div></a>`;return html.replace(/<a class="metric metric-progress"[^]*?<\/a>/,card);};
stageMap=lifecyclePanel;routeMap=lineagePanel;
const lifecycleNativeCard=buildCard;buildCard=(b,detail=false)=>{const r=P.ai_reviews.reviews.find(x=>x.id===b.key);let html=lifecycleNativeCard(b,detail);if(r)html=html.replace(/<span><b>☆☆☆☆☆<\/b>[^]*?<\/span>/,aiStars(r));return html;};
const lifecycleNativeHome=home;home=()=>lifecycleNativeHome().replace('<div class="sectionHead" id="builds">',aiFeatured()+'<div class="sectionHead" id="builds">');
const lifecycleNativeComparison=comparison;comparison=()=>lifecycleNativeComparison()+aiReviewPanel();
const lifecycleNativeReview=review;review=()=>{let html=lifecycleNativeReview();html=html.replace(t('评分','Rating')+'</label>',t('玩家体验分（非AI版本星级）','Player experience score (not the AI version rating)')+'</label>');return `<section class="review-distinction"><b>${t('版本星级与玩家反馈分开','Version stars and player feedback are separate')}</b><p>${t('版本星级由 AI 基于证据评审；这里和通关表记录玩家实际体验，不作为教学成绩，也不直接改写 AI 星级。','Version stars come from evidence-led AI review. This page and completion forms record player experience; they are not learning grades and do not directly rewrite AI stars.')}</p><a href="${link('comparison')}#ai-reviews">${t('查看 AI 理据与分数','Read AI scores and reasons')} ↗</a></section>`+html;};

// LIFECYCLE_OVERLAY_END
// PRECLASS_HUB_ADAPTER_BEGIN — extend the accepted R6 components, not the gameplay.
function prepBudget(){const c=P.cost,h=P.human,used=c.api_equivalent_aud,pct=used/P.budget*100;return `<section class="project-dashboard"><a class="metric metric-budget" href="${link('costs')}"><span class="metric-label">${t('MVP总预测 / 预算池','MVP forecast / pool')}</span><strong>A$${m(used)} <i>/ ${P.budget}</i></strong>${bar(+pct.toFixed(1),t('预测预算使用率','Forecast budget share'))}<div class="metric-caption"><b>${t('含两路预留，非已消费','Includes reserves, not actual spend')}</b><span>${t('历史与HUB估算','History/HUB estimate')} A$${m(c.recorded_estimate)}</span></div></a><a class="metric metric-progress" href="${link('development')}#lifecycle"><span class="metric-label">${t('本轮重制 · 三阶段总进度','This remake · three-phase progress')}</span><strong>${lp(overallPct())}<i>%</i></strong>${bar(+overallPct().toFixed(1),t('三阶段准备完成率','Three-phase preparation progress'))}<div class="metric-caption"><b>${t('MVP准备','MVP preparation')} ${phaseDone(P.lifecycle.phases[0])}/7</b><span>${t('历史成果不清零；新版尚未制作','History preserved; no remake built yet')}</span></div></a><a class="metric metric-human" href="${link('costs')}#human"><span class="metric-label">${t('同范围人工重建估值','Same-scope manual rebuild estimate')}</span><strong>≈ A$${whole(h.aud_mid)}</strong><div class="metric-bottom"><b>${range(h.hours_range,' h')}</b><span>${t('工作项规划，不是已花工时','Task plan, not measured hours')}</span></div></a><a class="metric metric-efficiency" href="${link('costs')}#efficiency"><span class="metric-label">${t('效率证据','Efficiency evidence')}</span><div class="ratio-pair"><div><strong>—<i>×</i></strong><small>${t('时间','Time')}</small></div><div><strong>—<i>×</i></strong><small>${t('成本','Cost')}</small></div></div><span class="metric-foot">${t('原有效计时与账单未回收，不编倍数','No original active-time/billing evidence; no invented ratio')}</span></a></section><details class="metric-method"><summary>${t('估算口径与当前范围','Estimate basis and current scope')}</summary><p>${v(P.cost_note)}</p></details>`;}
budget=prepBudget;
function prepCard(b){if(b.status==='planned')return `<article class="card modelcard planned-build" id="${b.key}" data-status="planned"><div class="branch-header"><span>${esc(b.tool)}</span><small>${t('独立重制候选','Independent remake candidate')}</small></div><div class="cardBody"><span class="badge">${t('准备就绪 · 尚未制作','Prepared · not built')}</span><h3>${v(b.name)}</h3><p>${v(b.subtitle)}</p><div class="planned-facts"><span>${t('试玩','Playable')} <b>${t('未生成','Not generated')}</b></span><span>${t('AI星级','AI stars')} <b>${t('未实现，不评分','Not built, not rated')}</b></span></div><p class="fine">${t('显示顺序不是评审结果；两条分支使用同一份需求与验收标准。','Display order is not a verdict. Both branches use the same brief and acceptance criteria.')}</p><div class="actions"><a class="btn primary" href="${link('rebuild')}#${b.key}">${t('查看重制准备','Review remake brief')} →</a><a class="btn" href="${b.task_file}" download>${t('任务文本','Task text')} ↓</a></div></div></article>`;
const r=P.ai_reviews.reviews.find(x=>x.id===b.key);return `<article class="card modelcard" id="${b.key}" data-status="baseline"><img class="photo" src="${b.image}" alt="${esc(v(b.name))}" loading="lazy"><div class="cardBody"><span class="badge">${t('现有历史基线 · 可试玩','Existing historical baseline · playable')}</span><h3>${v(b.name)}</h3><p>${v(b.strength)}</p><p class="build-note limit"><b>${t('边界','Limit')}</b>${v(b.limit)}</p>${r?aiStars(r):''}<div class="actions"><a class="btn primary" href="${gameLink(b)}">${t('试玩现有基线','Play existing baseline')} ↗</a><a class="btn" href="${link('review')}">${t('记录问题','Record feedback')}</a></div></div></article>`;}
buildCard=prepCard;
function prepLifecycle(){return `<section class="lifecycle-panel" id="lifecycle"><span id="stage-map"></span><div class="sectionHead"><div><span class="eyebrow">THREE-PHASE PRODUCT LIFECYCLE</span><h2>${t('本轮重制，先从MVP准备开始','Begin this remake with MVP preparation')}</h2></div><div class="lifecycle-total"><strong data-overall>${lp(overallPct())}%</strong><span>${t('三阶段里程碑覆盖率','Three-phase milestone coverage')}</span></div></div>${bar(+overallPct().toFixed(1),t('三阶段总进度','Overall progress'))}<p class="lifecycle-position">${v(P.lifecycle.current_note)}</p><div class="lifecycle-grid">${P.lifecycle.phases.map(lifecycleCard).join('')}</div><details class="metric-method"><summary>${t('算法与旧版成果的区别','Formula and the retained baseline')}</summary><p>${v(P.lifecycle.formula)}</p><p>${v(P.lifecycle.coverage_note)}</p><p class="formula">(2 ÷ 7 + 0 ÷ 8 + 0 ÷ 6) ÷ 3 = 9.5%</p></details></section>`;}
stageMap=prepLifecycle;lifecyclePanel=prepLifecycle;
function prepDownloads(){return `<section class="paper downloadBlock"><div><span class="eyebrow">ONE WORK · ONE HUB</span><h2>${t('本作品HUB与旧版单机包','This HUB and the baseline solo package')}</h2><p>${t('包含本HUB、双语记录、Mermaid图、重制任务文本和原版可玩文件；不含尚未制作的Opus/Astra游戏。电脑离线使用需已安装Node，按包内说明运行静态服务。','Contains this HUB, bilingual records, Mermaid diagrams, task briefs and baseline playable files—not nonexistent Opus/Astra remakes. Offline desktop use needs preinstalled Node and the included static-server instructions.')}</p></div><a class="btn primary" href="../downloads/preclass-20260926.zip" download>${t('下载本作品准备包','Download project preparation pack')} ↓</a></section>`;}
downloads=prepDownloads;
home=()=>{const future=P.branches.filter(b=>b.status==='planned'),old=P.branches.filter(b=>b.legacy),first=old[0];const pages=[['rebuild','01',t('共同Brief与两路任务','Shared brief and two model tasks')],['development','02',t('沟通、历史与版本图','Discussion, history and lineage')],['costs','03',t('完整估算与制作预留','Estimates and production reserves')],['parents','04',t('实践与学习记录','Practice and learning')],['comparison','05',t('AI理据与版本对照','AI rationale and comparison')],['review','06',t('课前试玩记录','Pre-class playtest record')]];
return budget()+`<section class="hero"><img class="cover" src="${P.hero}" alt="${esc(v(P.title))}"><div class="heroContent"><span class="eyebrow">${P.name} / PROJECT STUDIO</span><h1>${v(P.heroTitle)}</h1><p>${v(P.intro)}</p><div class="actions"><a class="btn primary" href="${link('rebuild')}">${t('进入两路重制准备','Open remake preparation')} →</a><a class="btn" href="${gameLink(first)}">${t('先试玩现有基线','Play the existing baseline')} ↗</a></div></div><span class="heroBadge">HUB R6 · ${t('课前准备','Pre-class preparation')}</span></section><div class="decision-panel"><span class="eyebrow">OPUS + ASTRA · PENDING IMPLEMENTATION</span><p>${v(P.decision)}</p></div><div class="sectionHead" id="builds"><div><span class="eyebrow">NEXT VERSIONS · NOT YET BUILT</span><h2>${t('新版区域：两条独立重制分支','New-version area: two independent remakes')}</h2></div></div><div class="two builds">${future.map(prepCard).join('')}</div>${stageMap()}<div class="sectionHead"><h2>${t('课前先对齐三件事','Three points to align before building')}</h2></div><section class="paper">${P.questions.map((x,i)=>`<div class="changeRow"><span class="changeNumber">${i+1}</span><h3>${v(x)}</h3></div>`).join('')}</section><div class="cards">${pages.map(([page,no,title])=>`<a class="card cardLink" href="${link(page)}"><div class="cardBody"><div class="icon">${no}</div><h3>${title}</h3><div class="arrow">${t('打开','Open')} ↗</div></div></a>`).join('')}</div>${routeMap()}<section class="history-zone" id="history"><div class="sectionHead"><div><span class="eyebrow">BASELINE ARCHIVE · SEPARATE FROM REMAKES</span><h2>${t('旧版成果：完整保留作对照','Historical work: retained for comparison')}</h2></div></div><div class="two builds">${old.map(prepCard).join('')}</div><p class="fine">${v(P.snapshot_note)}</p></section>${downloads()}`;};
comparison=()=>header(t('已实现的才评分，待制作的不冒充成果','Rate implemented work, not planned output'),t('新版候选目前只占位；下面的AI理据评审只针对已存在的旧版基线。','New candidates are placeholders. The evidence-led AI review below applies only to the existing baseline.'))+`<div class="two builds">${P.branches.filter(x=>x.status==='planned').map(prepCard).join('')}</div><section class="history-zone"><h2>${t('历史基线与AI评审','Baseline and AI assessment')}</h2>${P.branches.filter(x=>x.legacy).map(prepCard).join('')}</section>`+aiReviewPanel();
parents=()=>header(t('把课堂经历带进下一次制作','Carry classroom experience into the next build'),t('这里是有来源的需求与学习复盘。明天尚未发生的实践不会被提前写成已学会。','These are source-backed requirements and learning reflections. Tomorrow’s practice is not pre-written as completed learning.'))+P.learning.map((x,i)=>`<section class="paper learning"><span class="eyebrow">LEARNING ${String(i+1).padStart(2,'0')}</span><h2>${v(x.title)}</h2><div class="two"><div><h3>${t('已有实践','Recorded practice')}</h3><p>${v(x.practice)}</p><h3>${t('相关工程知识','Related engineering')}</h3><p>${v(x.knowledge)}</p></div><div><h3>${t('结构化表达模板','Structured expression pattern')}</h3><blockquote>${v(x.expression)}</blockquote><p class="fine">${v(x.level)}</p></div></div></section>`).join('')+`<section class="paper"><h2>${t('下一堂的实践目标','Next lesson’s practice goals')}</h2><p>${t('试玩旧版→说出具体变化→让AI复述目标、约束和验证方法→同一Brief两路实现→用相同标准比较。这里只准备流程，不宣称已经完成课堂。','Play the baseline → specify changes → ask AI to restate goals/constraints/tests → build independently from one brief → compare by the same criteria. This is preparation, not a claim that the lesson has happened.')}</p><a class="btn primary" href="${link('review')}">${t('记录我的观察','Record my observations')}</a></section>`;
costs=()=>header(t('完整MVP估算：历史、准备与未来预留分开','Complete MVP estimate: history, preparation and reserves'),t('没有找回的原账单用有界估算；尚未实施的两路重制只作规划预留，不称已花费。','Missing original bills use bounded estimates. The unbuilt remakes are planning reserves, not expenditure.'))+budget()+`<section class="paper"><h2>${t('预算账本','Budget ledger')}</h2><div class="tableWrap"><table><thead><tr><th>${t('阶段','Stage')}</th><th>AUD</th><th>${t('范围','Range')}</th><th>${t('性质与依据','Type and basis')}</th></tr></thead><tbody>${P.cost.items.map(x=>`<tr><td>${v(x.title)}</td><td>${m(x.aud)}</td><td>${m(x.range[0])}–${m(x.range[1])}</td><td><b>${x.kind==='reserve'?t('未来预留，未发生','Future reserve, not incurred'):t('工具等值估算','Tool-equivalent estimate')}</b><br>${v(x.note)}</td></tr>`).join('')}<tr><th>${t('MVP总预测','MVP forecast')}</th><th>${m(P.cost.api_equivalent_aud)}</th><td>${m(P.cost.range[0])}–${m(P.cost.range[1])}</td><td>${t('实际执行前按范围再核预算；高位估计超池时不可静默超支。','Reconfirm scope/budget before execution; upper estimates exceeding the pool do not authorize overspend.')}</td></tr></tbody></table></div><p>${v(P.cost_note)}</p><p>${t('本轮预算不包括正式故事、美术、音乐、音效、配音全量生产及商业平台运营；它们在后续两阶段另行定范围与预算。','This estimate excludes full story/art/music/sound/voice production and commercial operations; later phases need their own scope and budget.')}</p><a class="btn" href="budget.json">${t('预算数据','Budget data')} ↗</a></section>${humanSection()}<section class="paper" id="efficiency"><h2>${t('不制造效率倍数','No invented efficiency multiplier')}</h2><p>${t('当前没有完整有效计时和原始API账单，不能用猜测分母得出时间或成本倍率。人工估值沿用R6的A$63.44/h历史规划参数，与教师工资和真实费用无关。','No complete active-time or API bill is available, so no time/cost multiplier is inferred. Manual valuation uses the R6 historical A$63.44/hour planning parameter, not teacher wages or actual spend.')}</p></section>`;
guide=()=>header(t('现有基线怎样试玩','How to play the existing baseline'),t('这次只适配HUB。旧游戏逻辑与原界面语言不改；新版双语和输入要求已写入重制验收。','This pass adapts the HUB only. Baseline logic and its original UI language remain unchanged; remake language/input requirements are in the acceptance brief.'))+`<section class="paper"><h2>${v(P.legacy_name)}</h2><p>${v(P.guide)}</p><div class="actions"><a class="btn primary" href="${gameLink(P.branches.find(b=>b.legacy))}">${t('打开旧版单机','Open baseline solo')} ↗</a><a class="btn" href="${link('rebuild')}">${t('查看重制验收','Remake acceptance')}</a></div><p>${t('试玩外层始终有返回HUB入口；保留原游戏界面与操作限制。完整双语、可靠暂停与独立存档属于两条重制的验收要求。','The preview shell has a permanent HUB return. Original game UI and control limits remain; full bilingual play, reliable pause and isolated saves are acceptance requirements for both remakes.')}</p></section>${downloads()}`;
labels.rebuild=['重制准备','Remake preparation'];
function remakePage(){return header(t('同一份需求，两条独立实现','One brief, two independent implementations'),t('本页已准备好需求和回执位置；复制文本不会自动调用模型、执行制作或产生新版游戏。','Requirements and handoff locations are ready. Copying a task does not invoke a model, start production or create a game.'))+`<section class="paper"><h2>${t('已有核心要求','Existing core requirements')}</h2><div class="brief-grid">${P.remake.requirements.map(x=>`<div><code>${x.id}</code><h3>${v(x.title)}</h3><p>${v(x.detail)}</p><p class="fine"><b>${t('验证','Acceptance')}</b> ${v(x.acceptance)}</p></div>`).join('')}</div><h3>${t('本轮不做','Out of scope')}</h3><p>${v(P.remake.scope_out)}</p></section><section class="paper"><h2>${t('两条分支共同验收','Shared acceptance for both branches')}</h2>${P.remake.tests.map((x,i)=>`<div class="changeRow"><span class="changeNumber">${i+1}</span><p>${v(x)}</p></div>`).join('')}</section><div class="two">${['opus','astra'].map(name=>`<section class="paper task-panel" id="remake-${name}"><span class="badge">${t('待课堂指令后执行','Awaiting classroom execution instruction')}</span><h2>${name==='opus'?'Opus':'Astra'} · ${t('独立重制','Independent remake')}</h2><p>${t('输出目录','Output folder')}: <code>rebuild/${name}/</code></p><p>${t('模型可自行选择实现方法，但不可覆盖旧版或读取对手未完成方案来假装独立。','The model may choose implementation methods, but must not overwrite the baseline or claim independence after copying the other candidate.')}</p><div class="actions"><button type="button" class="btn primary" data-copy-task="${name}">${t('复制任务','Copy task')}</button><a class="btn" href="../rebuild/${name}/task.txt" download>${t('下载文本','Download text')}</a></div><textarea class="task-copy-area" id="task-${name}" readonly aria-label="${name} task" hidden></textarea><p class="copy-status" id="copy-status-${name}" role="status"></p></section>`).join('')}</div><section class="paper"><h2>${t('交付后的收敛规则','Convergence after delivery')}</h2><p>${t('两版分别实现和QA，再由AI按同一维度给理据评分；依据证据选择主线。优点融合只有被明确决定且确实实施后才画成源码合并。没有代码、试玩、测试证据的分支保持未交付，不显示星级。','Implement and QA independently, then use the same evidence-led AI rubric to select a mainline. Show a source merge only after it is explicitly chosen and actually performed. Without code/play/tests, a branch stays undelivered and unrated.')}</p><a href="../rebuild/manifest.json">${t('查看分支与交付登记','Branch and delivery manifest')} ↗</a></section>`;}
const prepOriginalSetup=setup;setup=()=>{prepOriginalSetup();document.querySelectorAll('[data-copy-task]').forEach(button=>button.onclick=async()=>{const name=button.dataset.copyTask,area=document.getElementById('task-'+name),status=document.getElementById('copy-status-'+name);try{const r=await fetch('../rebuild/'+name+'/task.txt');if(!r.ok)throw Error('task missing');const text=await r.text();area.value=text;area.hidden=false;try{await navigator.clipboard.writeText(text);status.textContent=t('已复制；尚未启动制作。','Copied; production has not started.');}catch{area.focus();area.select();status.textContent=t('文本已选中，可手动复制；不会自动执行。','Text selected for manual copying; nothing runs automatically.');}}catch(err){status.textContent=t('读取失败，请使用下载链接。','Unable to load; use the download link.');}});};
const prepOriginalRender=render;render=()=>{if(Q==='rebuild'){Q='guide';prepOriginalRender();Q='rebuild';app.innerHTML=remakePage();document.title=v(P.title)+' · '+v(labels.rebuild);setup();}else prepOriginalRender();window.__prepHub={revision:P.preparation_revision,project:P.id,remakes:'PLANNED_NOT_STARTED',phase1:P.lifecycle.phases[0].completed_gates,overall:P.lifecycle.overall_percent};};
// PRECLASS_HUB_ADAPTER_END

document.documentElement.lang=L?'en':'zh-CN';if(!document.getElementById('language'))document.getElementById('nav').insertAdjacentHTML('beforeend',languageButton());bindLanguageButton();
fetch('project.json?v=r6-preclass-20260926').then(r=>{if(!r.ok)throw Error('Missing studio data');return r.json();}).then(d=>{D=d;P=d.projects[document.body.dataset.project];Q=document.body.dataset.page;render();window.__studio={project:P.id,release:D.release,nativeBaseline:'CLASSROOM-HUB-R5-20260923'};window.__studioData=P;window.__hubLifecycle={revision:P.presentation_revision,overall:P.lifecycle.overall_percent,phase1:P.lifecycle.phases[0].completion_percent};window.__hubLifecycle={revision:P.presentation_revision,overall:P.lifecycle.overall_percent,phase1:P.lifecycle.phases[0].completion_percent};}).catch(e=>{app.innerHTML='<h1>Unable to load project / 作品读取失败</h1><p>'+esc(e.message)+'</p>';});})();